static void Link(CThingList& l, CThingList::SNode* head, CThingList::SNode* nodes, CThing** things, int n)
{
    l.m_pHead = head; head->m_pNext = head; head->m_pPrev = head;
    for (int i = 0; i < n; ++i) {
        CThingList::SNode* nd = &nodes[i];
